//This query shows the number behind the effectiveness of phish and malware false positives including post delivery events but without edge data detections.
let minTime = toscalar(EmailEvents | summarize min(Timestamp));
let maxTime = toscalar(EmailEvents | summarize max(Timestamp));

// Get all mailflow detected as clean at time of delivery 
let EmailEventsClean = materialize( 
    EmailEvents 
    | where Timestamp between (toscalar(minTime) .. toscalar(maxTime)) and EmailDirection == "Inbound" 
    | where ThreatTypes !contains "Phish" and ThreatTypes !contains "Malware" // UN-comment this when using sentinel or another streaming SIEM (line 10).
    // this alteration is due to the threat types being updated directly within advanced hunting.
    //| where DeliveryLocation != "Quarantine" // comment out this line if you uncomment line 10, as it's only required for advanced hunting.
    | project NetworkMessageId,ThreatTypes 
); 
// Get all mailflow detected as phish or malware at time of delivery 
let EmailEventsThreats = materialize( 
    EmailEvents 
    | where Timestamp between (toscalar(minTime) .. toscalar(maxTime)) and EmailDirection == "Inbound" 
    | where ThreatTypes contains "Phish" or ThreatTypes contains "Malware" 
    | extend MDO_detection = parse_json(DetectionMethods) 
    | extend FirstDetection = iif(isempty(MDO_detection), "Clean", tostring(bag_keys(MDO_detection)[0])) 
    | extend FirstSubcategory = iif(FirstDetection != "Clean" and array_length(MDO_detection[FirstDetection]) > 0, strcat(FirstDetection, ": ", tostring(MDO_detection[FirstDetection][0])), "No Detection (clean)") 
    | project NetworkMessageId,FirstDetection,FirstSubcategory,MDO_detection,ThreatTypes 
); 
// Get all post delivery ZAP / Redelivery events, and arg_max them to ensure we have the latest verdict to work with for each 
let EmailPostDeliveryFiltered = materialize( 
    EmailPostDeliveryEvents 
    | where Timestamp between (toscalar(minTime) .. datetime_add('day', 7, toscalar(maxTime))) 
    | where ActionType in ("Malware ZAP","Phish ZAP") or Action has_any ("Redelivery","Reprocessed") 
    | extend Key = strcat(NetworkMessageId , "-", RecipientEmailAddress) 
    | summarize arg_max(Timestamp, *) by Key 
    | project Action,ActionType,ActionResult,ThreatTypes,NetworkMessageId 
); 
// Optional - get all admin submissions for malware or phish, so we can also count these in the miss bucket. 
let CloudAppEventsFiltered = materialize( 
    CloudAppEvents 
    | where Timestamp between (toscalar(minTime) .. datetime_add('day', 7, toscalar(maxTime)))
    | where ActionType == "AdminSubmissionSubmitted" 
    | extend SubmissionType = tostring(parse_json(RawEventData).SubmissionType) 
    | extend NetworkMessageId = tostring(parse_json(RawEventData).ObjectId) 
    | where SubmissionType in ("1", "2") 
    | project SubmissionType,NetworkMessageId 
); 
// get the number of threats caught in mailflow 
let Mal_Phish_Mailflow = toscalar( 
    EmailEventsThreats 
    | summarize count() 
); 
// get the number of threats caught in mailflow which turned out to be false positives (FPs) so we can correct the calculation 
let FP_ZAP = toscalar( 
    EmailPostDeliveryFiltered 
    | where ThreatTypes !contains "Phish" and ThreatTypes !contains "Malware" and Action has_any ("Redelivery","Reprocessed") 
    | join kind=leftsemi (EmailEventsThreats) on NetworkMessageId 
    | summarize count() 
); 
// get the number of threats successfully cleaned up post delivery, ignoring where administrative policy stopped action 
let FN_ZAP_Successful = toscalar( 
    EmailPostDeliveryFiltered 
    | where ActionType in ("Malware ZAP","Phish ZAP") and ActionResult in ("Success","AdminPolicy") 
    | join kind=leftsemi (EmailEventsClean) on NetworkMessageId 
    | summarize count() 
); 
// get the number of threats unsuccessfully cleaned up post delivery. 
let FN_ZAP_Unsuccessful = toscalar( 
    EmailPostDeliveryFiltered 
    | where ActionType in ("Malware ZAP","Phish ZAP") and ActionResult !in ("Success","AdminPolicy") 
    | join kind=leftsemi (EmailEventsClean) on NetworkMessageId 
    | summarize count() 
); 
// join the administrative submissions to clean mailflow to find the additional miss 
let FN_Admin_Submissions = toscalar( 
    CloudAppEventsFiltered 
    | join kind=rightsemi (EmailEventsClean) on NetworkMessageId 
    | summarize count() 
    ); 
    // print each result, and run the calculation to work out effectiveness at time of delivery and post delivery. 

print StatisticName="Effectiveness Post Delivery", Value=abs(round(((toreal(toscalar(FN_Admin_Submissions))+toreal(toscalar(FN_ZAP_Unsuccessful)))/(toreal(toscalar(Mal_Phish_Mailflow))+toreal(toscalar(FN_ZAP_Successful))+toreal(toscalar(FN_ZAP_Unsuccessful))+toreal(toscalar(FN_Admin_Submissions))-toreal(toscalar(FP_ZAP)))*100-100),2))

//This query shows the number behind the effectiveness of phish and malware false positives including post delivery events but without edge data detections.
let minTime = toscalar(EmailEvents | summarize min(Timestamp));
let maxTime = toscalar(EmailEvents | summarize max(Timestamp));

// Get all mailflow detected as clean at time of delivery 
let EmailEventsClean = materialize( 
    EmailEvents 
    | where Timestamp between (toscalar(minTime) .. toscalar(maxTime)) and EmailDirection == "Inbound" 
    | where ThreatTypes !contains "Phish" and ThreatTypes !contains "Malware" // UN-comment this when using sentinel or another streaming SIEM (line 10).
    // this alteration is due to the threat types being updated directly within advanced hunting.
    //| where DeliveryLocation != "Quarantine" // comment out this line if you uncomment line 10, as it's only required for advanced hunting.
    | project NetworkMessageId,ThreatTypes 
); 
// Get all mailflow detected as phish or malware at time of delivery 
let EmailEventsThreats = materialize( 
    EmailEvents 
    | where Timestamp between (toscalar(minTime) .. toscalar(maxTime)) and EmailDirection == "Inbound" 
    | where ThreatTypes contains "Phish" or ThreatTypes contains "Malware" 
    | extend MDO_detection = parse_json(DetectionMethods) 
    | extend FirstDetection = iif(isempty(MDO_detection), "Clean", tostring(bag_keys(MDO_detection)[0])) 
    | extend FirstSubcategory = iif(FirstDetection != "Clean" and array_length(MDO_detection[FirstDetection]) > 0, strcat(FirstDetection, ": ", tostring(MDO_detection[FirstDetection][0])), "No Detection (clean)") 
    | project NetworkMessageId,FirstDetection,FirstSubcategory,MDO_detection,ThreatTypes 
); 
// Get all post delivery ZAP / Redelivery events, and arg_max them to ensure we have the latest verdict to work with for each 
let EmailPostDeliveryFiltered = materialize( 
    EmailPostDeliveryEvents 
    | where Timestamp between (toscalar(minTime) .. datetime_add('day', 7, toscalar(maxTime))) 
    | where ActionType in ("Malware ZAP","Phish ZAP") or Action has_any ("Redelivery","Reprocessed") 
    | extend Key = strcat(NetworkMessageId , "-", RecipientEmailAddress) 
    | summarize arg_max(Timestamp, *) by Key 
    | project Action,ActionType,ActionResult,ThreatTypes,NetworkMessageId 
); 
// Optional - get all admin submissions for malware or phish, so we can also count these in the miss bucket. 
let CloudAppEventsFiltered = materialize( 
    CloudAppEvents 
    | where Timestamp between (toscalar(minTime) .. datetime_add('day', 7, toscalar(maxTime)))
    | where ActionType == "AdminSubmissionSubmitted" 
    | extend SubmissionType = tostring(parse_json(RawEventData).SubmissionType) 
    | extend NetworkMessageId = tostring(parse_json(RawEventData).ObjectId) 
    | where SubmissionType in ("1", "2") 
    | project SubmissionType,NetworkMessageId 
); 
// get the number of threats caught in mailflow 
let Mal_Phish_Mailflow = toscalar( 
    EmailEventsThreats 
    | summarize count() 
); 
// get the number of threats caught in mailflow which turned out to be false positives (FPs) so we can correct the calculation 
let FP_ZAP = toscalar( 
    EmailPostDeliveryFiltered 
    | where ThreatTypes !contains "Phish" and ThreatTypes !contains "Malware" and Action has_any ("Redelivery","Reprocessed") 
    | join kind=leftsemi (EmailEventsThreats) on NetworkMessageId 
    | summarize count() 
); 
// get the number of threats successfully cleaned up post delivery, ignoring where administrative policy stopped action 
let FN_ZAP_Successful = toscalar( 
    EmailPostDeliveryFiltered 
    | where ActionType in ("Malware ZAP","Phish ZAP") and ActionResult in ("Success","AdminPolicy") 
    | join kind=leftsemi (EmailEventsClean) on NetworkMessageId 
    | summarize count() 
); 
// get the number of threats unsuccessfully cleaned up post delivery. 
let FN_ZAP_Unsuccessful = toscalar( 
    EmailPostDeliveryFiltered 
    | where ActionType in ("Malware ZAP","Phish ZAP") and ActionResult !in ("Success","AdminPolicy") 
    | join kind=leftsemi (EmailEventsClean) on NetworkMessageId 
    | summarize count() 
); 
// join the administrative submissions to clean mailflow to find the additional miss 
let FN_Admin_Submissions = toscalar( 
    CloudAppEventsFiltered 
    | join kind=rightsemi (EmailEventsClean) on NetworkMessageId 
    | summarize count() 
    ); 
    // print each result, and run the calculation to work out effectiveness at time of delivery and post delivery. 
union withsource=Table 
    (print StatisticName="Mal/Phish Mailflow totals - Minus FPs", Value=toreal(Mal_Phish_Mailflow) - toreal(FP_ZAP)), 
    (print StatisticName="Admin Mal/Phish FNs Submitted", Value=toreal(FN_Admin_Submissions)), 
    (print StatisticName="Mal/Phish FPs Reverse Zapped", Value=toreal(FP_ZAP)), 
    (print StatisticName="Mal / Phish Successfully Zapped", Value=toreal(FN_ZAP_Successful)), 
    (print StatisticName="Mal / Phish UN-Successfully Zapped", Value=toreal(FN_ZAP_Unsuccessful)), 
    (print StatisticName="Effectiveness Post Delivery (%)", Value=abs(round(((toreal(FN_Admin_Submissions)+toreal(FN_ZAP_Unsuccessful))/(toreal(Mal_Phish_Mailflow)+toreal(FN_ZAP_Successful)+toreal(FN_ZAP_Unsuccessful)+toreal(FN_Admin_Submissions)-toreal(FP_ZAP))*100-100),2))), 
    (print StatisticName="Effectiveness Pre-Delivery (%)", Value=abs(round(((toreal(FN_Admin_Submissions)+toreal(FN_ZAP_Unsuccessful)+toreal(FN_ZAP_Successful))/(toreal(Mal_Phish_Mailflow)+toreal(FN_ZAP_Successful)+toreal(FN_ZAP_Unsuccessful)+toreal(FN_Admin_Submissions)-toreal(FP_ZAP))*100-100),2))) 
| project StatisticName, Value

let base = materialize(EmailEvents
| where EmailDirection == "Inbound"
| summarize arg_max(Timestamp, ThreatTypes, DeliveryAction, OrgLevelPolicy, OrgLevelAction, UserLevelAction) by Key = strcat(NetworkMessageId, "-", RecipientEmailAddress));
let agg = materialize(base | summarize
    Total = count(),
    Filtered = countif(isnotempty(ThreatTypes) and DeliveryAction != "Delivered" and OrgLevelPolicy !in ("Phishing simulation", "SecOps Mailbox")),
    FMal = countif(ThreatTypes has "Malware" and OrgLevelPolicy !in ("Phishing simulation", "SecOps Mailbox")),
    FPhish = countif(ThreatTypes has "Phish" and not(ThreatTypes has "Malware") and DeliveryAction != "Delivered" and OrgLevelPolicy !in ("Phishing simulation", "SecOps Mailbox")),
    FSpam = countif(ThreatTypes == "Spam" and DeliveryAction != "Delivered" and OrgLevelPolicy !in ("Phishing simulation", "SecOps Mailbox")),
    Deliv = countif(isnotempty(ThreatTypes) and DeliveryAction == "Delivered" and (isnotempty(OrgLevelAction) or isnotempty(UserLevelAction))),
    Blocked = countif(isempty(ThreatTypes) and DeliveryAction != "Delivered" and (isnotempty(OrgLevelAction) or isnotempty(UserLevelAction))),
    Clean = countif(isempty(ThreatTypes) and DeliveryAction == "Delivered"));
let pd = materialize(EmailPostDeliveryEvents | where ActionResult == "Success" | summarize MalZap = countif(ActionType == "Malware ZAP"), PhishZap = countif(ActionType == "Phish ZAP"), SpamZap = countif(ActionType == "Spam ZAP"));
let sub = materialize(CloudAppEvents | extend R = tostring(parse_json(RawEventData).RecordType), SCT = tostring(parse_json(RawEventData).SubmissionContentType) | where R == "29" | summarize Adm = countif(ActionType == "AdminSubmissionSubmitted" and SCT == "Mail"), Usr = countif(ActionType == "UserSubmission"));
let Total = toscalar(agg | project Total);
let Filtered = toscalar(agg | project Filtered);
let FMal = toscalar(agg | project FMal);
let FPhish = toscalar(agg | project FPhish);
let FSpam = toscalar(agg | project FSpam);
let Deliv = toscalar(agg | project Deliv);
let Blocked = toscalar(agg | project Blocked);
let Clean = toscalar(agg | project Clean);
let MalZap = toscalar(pd | project MalZap);
let PhishZap = toscalar(pd | project PhishZap);
let SpamZap = toscalar(pd | project SpamZap);
let Adm = toscalar(sub | project Adm);
let Usr = toscalar(sub | project Usr);
union
    (print o = 1, Name = "Total Inbound Emails", Count = Total),
    (print o = 2, Name = "    Filtering Totals", Count = Filtered),
    (print o = 3, Name = "        Filtered as Malware", Count = FMal),
    (print o = 4, Name = "        Filtered as Phish", Count = FPhish),
    (print o = 5, Name = "        Filtered as Spam", Count = FSpam),
    (print o = 6, Name = "    Delivered with Detection", Count = Deliv),
    (print o = 7, Name = "    User/Admin Blocked", Count = Blocked),
    (print o = 8, Name = "    Clean Emails", Count = Clean),
    (print o = 9, Name = "Post-Delivery ZAP Removals", Count = MalZap + PhishZap + SpamZap),
    (print o = 10, Name = "    Removed by Malware ZAP", Count = MalZap),
    (print o = 11, Name = "    Removed by Phish ZAP", Count = PhishZap),
    (print o = 12, Name = "    Removed by Spam ZAP", Count = SpamZap),
    (print o = 13, Name = "User/Admin Reported", Count = Adm + Usr),
    (print o = 14, Name = "    Reported by Admins", Count = Adm),
    (print o = 15, Name = "    Reported by Users", Count = Usr)
| sort by o asc
| extend ["% of Inbound"] = round(Count * 100.0 / Total, 1)
| project Name, Count, ["% of Inbound"]

//Headline Microsoft Teams / collaboration protection metrics for the executive summary, with per-interval sparklines so the collaboration threat trend is visible at a glance. Messages and URLs are counted per distinct Teams message.
let gran = {Granularity};
let me = materialize(MessageEvents);
let cae = materialize(CloudAppEvents | where ActionType == "TeamsImpersonationDetected");
let mui = materialize(MessageUrlInfo);
let uce = materialize(UrlClickEvents | where Workload == "Teams" and ActionType in ("ClickBlocked","ClickBlockedByTenantPolicy"));
let fmc = materialize(FileMaliciousContentInfo | where Workload == "MicrosoftTeams");
union
(me | summarize Count = dcount(TeamsMessageId) | extend Details = "Teams Messages Scanned", Ord = 1, Trend = toscalar(me | make-series S = count() default = 0 on Timestamp step gran | project S)),
(me | where isnotempty(ThreatTypes) | summarize Count = count() | extend Details = "Teams Threat Messages", Ord = 2, Trend = toscalar(me | where isnotempty(ThreatTypes) | make-series S = count() default = 0 on Timestamp step gran | project S)),
(cae | summarize Count = count() | extend Details = "Teams Impersonation Detections", Ord = 3, Trend = toscalar(cae | make-series S = count() default = 0 on Timestamp step gran | project S)),
(mui | summarize Count = dcount(TeamsMessageId) | extend Details = "URLs Shared in Teams", Ord = 4, Trend = toscalar(mui | make-series S = count() default = 0 on Timestamp step gran | project S)),
(uce | summarize Count = count() | extend Details = "Malicious Clicks Blocked", Ord = 5, Trend = toscalar(uce | make-series S = count() default = 0 on Timestamp step gran | project S)),
(fmc | summarize Count = count() | extend Details = "Teams Files Scanned", Ord = 6, Trend = toscalar(fmc | make-series S = count() default = 0 on Timestamp step gran | project S)),
(fmc | where isnotempty(ThreatTypes) | summarize Count = count() | extend Details = "Malicious Teams Files", Ord = 7, Trend = toscalar(fmc | where isnotempty(ThreatTypes) | make-series S = count() default = 0 on Timestamp step gran | project S))
| sort by Ord asc
| project Details, Count, Trend

//KPI summary of inbound email malware detections for the selected period, with a per-period Trend series feeding each tile sparkline.
let gran = {Granularity};
let mal = EmailEvents | where EmailDirection == "Inbound" | where ThreatTypes has "Malware";
let inbox = mal | where DeliveryLocation has "Inbox";
let malTrend = toscalar(mal | make-series Trend = count() default = 0 on Timestamp step gran | project Trend);
let inboxTrend = toscalar(inbox | make-series Trend = count() default = 0 on Timestamp step gran | project Trend);
union
(print Count = toscalar(mal | summarize count()), Details = "Malware Emails", Ord = 1, Trend = malTrend),
(print Count = toscalar(mal | summarize dcount(RecipientEmailAddress)), Details = "Users Targeted", Ord = 2, Trend = malTrend),
(print Count = toscalar(mal | summarize dcount(SenderFromDomain)), Details = "Sender Domains", Ord = 3, Trend = malTrend),
(print Count = toscalar(inbox | summarize count()), Details = "Delivered to Inbox", Ord = 4, Trend = inboxTrend)
| sort by Ord asc
| project Count, Details, Trend

//KPI summary of inbound email phishing detections for the selected period, with a per-period Trend series feeding each tile sparkline.
let gran = {Granularity};
let ph = EmailEvents | where EmailDirection == "Inbound" | where ThreatTypes has "Phish";
let inbox = ph | where DeliveryLocation has "Inbox";
let phTrend = toscalar(ph | make-series Trend = count() default = 0 on Timestamp step gran | project Trend);
let inboxTrend = toscalar(inbox | make-series Trend = count() default = 0 on Timestamp step gran | project Trend);
union
(print Count = toscalar(ph | summarize count()), Details = "Phish Emails", Ord = 1, Trend = phTrend),
(print Count = toscalar(ph | summarize dcount(RecipientEmailAddress)), Details = "Users Targeted", Ord = 2, Trend = phTrend),
(print Count = toscalar(ph | summarize dcount(SenderFromDomain)), Details = "Sender Domains", Ord = 3, Trend = phTrend),
(print Count = toscalar(inbox | summarize count()), Details = "Delivered to Inbox", Ord = 4, Trend = inboxTrend)
| sort by Ord asc
| project Count, Details, Trend

//This query visualises total emails with Phish detections over time summarizing the data daily.
//The comment in the query excludes deliveries to the SecOps Mailbox and by the Phish Simulation system. Remove the "//" to apply the exclusion.
let gran = {Granularity};
let agg = materialize(EmailEvents
| where OrgLevelPolicy != "Phishing simulation" and OrgLevelPolicy != "SecOps Mailbox"
| extend Key = strcat(NetworkMessageId , '-', RecipientEmailAddress) 
| summarize arg_max(Timestamp, *) by Key
| where ThreatTypes has "Phish"
| summarize PhishDetections = count() by Timestamp = bin(Timestamp, gran));
range Timestamp from toscalar(agg | summarize min(Timestamp)) to toscalar(agg | summarize max(Timestamp)) step gran
| join kind=leftouter (agg) on Timestamp
| project Timestamp, PhishDetections = coalesce(PhishDetections, 0)
| sort by Timestamp asc

//This query visualises total emails with Phish detections over time summarizing the data daily by Phish detection technologies/controls used for detecting unknown-unique phish.
let gran = {Granularity};
let minTime = toscalar(EmailEvents | summarize min(Timestamp));
let maxTime = toscalar(EmailEvents | summarize max(Timestamp));
let agg = materialize(EmailEvents
| where OrgLevelPolicy != "Phishing simulation" and OrgLevelPolicy != "SecOps Mailbox"
| extend Key = strcat(NetworkMessageId , '-', RecipientEmailAddress) 
| summarize arg_max(Timestamp, *) by Key
| where DetectionMethods has "Phish"
| project Timestamp, RecipientEmailAddress, NetworkMessageId, DT=parse_json(DetectionMethods)
| evaluate bag_unpack(DT)
| summarize ["File detonation"]=countif(Phish has 'File detonation' and Phish !has 'File detonation reputation'), ["URL detonation"]=countif(Phish has 'URL detonation' and Phish !has 'URL detonation reputation') by Timestamp = bin(Timestamp, gran));
range Timestamp from bin(minTime, gran) to bin(maxTime, gran) step gran
| join kind=leftouter (agg) on Timestamp
| project Timestamp, ["File detonation"]=coalesce(["File detonation"],0), ["URL detonation"]=coalesce(["URL detonation"],0)
| sort by Timestamp asc

//This query visualises total emails with Phish detections summarizing the data by intent of the message.
// Microsoft Defender for Office 365 LLM analysis is analyzing email messages to understand the intent of the messages. These threat classifications are then used in filtering decisions.
//The comment in the query excludes deliveries to the SecOps Mailbox and by the Phish Simulation system. Remove the "//" to apply the exclusion.
EmailEvents 
| where OrgLevelPolicy != "Phishing simulation" and OrgLevelPolicy != "SecOps Mailbox"
| extend Key = strcat(NetworkMessageId , '-', RecipientEmailAddress) 
| summarize arg_max(Timestamp, *) by Key
| where ThreatTypes has 'Phish' and ThreatClassification  has_any("Business intelligence","Contact establishment","Gift card","Invoice","Payroll","PII gathering","Task")
| summarize count() by ThreatClassification
| sort by count_ desc

//This query visualises total emails with Phish detections over time summarizing the data daily by Delivery Location.
//The comment in the query excludes deliveries to the SecOps Mailboxes and by the Phish Simulation system. Remove the "//" to apply the exclusion.
let gran = {Granularity};
let agg = materialize(EmailEvents
| where OrgLevelPolicy != "Phishing simulation" and OrgLevelPolicy != "SecOps Mailbox"
| extend Key = strcat(NetworkMessageId , '-', RecipientEmailAddress) 
| summarize arg_max(Timestamp, *) by Key
| where DetectionMethods has "Phish" and EmailDirection == "Inbound"
| summarize TotalPhishDetections=count(), Quarantine=countif(DeliveryLocation == "Quarantine"), Junkfolder=countif(DeliveryLocation == "Junk folder"), Inbox=countif(DeliveryLocation == "Inbox/folder"), Failed=countif(DeliveryLocation == "Failed"), Dropped=countif(DeliveryLocation == "Dropped") by Timestamp = bin(Timestamp, gran));
range Timestamp from toscalar(agg | summarize min(Timestamp)) to toscalar(agg | summarize max(Timestamp)) step gran
| join kind=leftouter (agg) on Timestamp
| project Timestamp, TotalPhishDetections=coalesce(TotalPhishDetections,0), Quarantine=coalesce(Quarantine,0), Junkfolder=coalesce(Junkfolder,0), Inbox=coalesce(Inbox,0), Failed=coalesce(Failed,0), Dropped=coalesce(Dropped,0)
| sort by Timestamp asc

//This query visualises total emails with Phish detections over time summarizing the data daily by various Phish Detection technologies/controls in Microsoft Defender for Office 365.
//The comment in the query excludes deliveries to the SecOps Mailbox and by the Phish Simulation system. Remove the "//" to apply the exclusion.
let gran = {Granularity};
let minTime = toscalar(EmailEvents | summarize min(Timestamp));
let maxTime = toscalar(EmailEvents | summarize max(Timestamp));
let agg = materialize(EmailEvents
| where OrgLevelPolicy != "Phishing simulation" and OrgLevelPolicy != "SecOps Mailbox"
| extend Key = strcat(NetworkMessageId , '-', RecipientEmailAddress)
| summarize arg_max(Timestamp, *) by Key
| where DetectionMethods has "Phish"
| mv-expand Details = parse_json(DetectionMethods).Phish to typeof(string)
| where isnotempty(Details)
| summarize Count = count() by Details, Timestamp = bin(Timestamp, gran));
range Timestamp from bin(minTime, gran) to bin(maxTime, gran) step gran
| extend d = 1 | join kind=inner (agg | distinct Details | extend d = 1) on d | project Timestamp, Details
| join kind=leftouter (agg) on Timestamp, Details
| project Timestamp, Details, Count = coalesce(Count, 0)
| sort by Details asc, Timestamp asc

//KPI summary of inbound email spam detections for the selected period, with a per-period Trend series feeding each tile sparkline.
let gran = {Granularity};
let sp = EmailEvents | where EmailDirection == "Inbound" | where ThreatTypes has "Spam";
let junk = sp | where DeliveryLocation has "Junk";
let spTrend = toscalar(sp | make-series Trend = count() default = 0 on Timestamp step gran | project Trend);
let junkTrend = toscalar(junk | make-series Trend = count() default = 0 on Timestamp step gran | project Trend);
union
(print Count = toscalar(sp | summarize count()), Details = "Spam Emails", Ord = 1, Trend = spTrend),
(print Count = toscalar(sp | summarize dcount(RecipientEmailAddress)), Details = "Users Targeted", Ord = 2, Trend = spTrend),
(print Count = toscalar(sp | summarize dcount(SenderFromDomain)), Details = "Sender Domains", Ord = 3, Trend = spTrend),
(print Count = toscalar(junk | summarize count()), Details = "Sent to Junk", Ord = 4, Trend = junkTrend)
| sort by Ord asc
| project Count, Details, Trend

//This query calculates the effectiveness of spam detections without edge data.
let minTime = toscalar(EmailEvents | summarize min(Timestamp));
let maxTime = toscalar(EmailEvents | summarize max(Timestamp));
// baseQuery _FN_Admin_Submissions_SPM
let _FN_Admin_Submissions_SPM = toscalar(
CloudAppEvents
| where Timestamp between (minTime .. maxTime)
| where ActionType == "AdminSubmissionSubmitted"
| extend SubmissionType = tostring((parse_json(RawEventData)).SubmissionType)
| extend NetworkMessageId = tostring((parse_json(RawEventData)).ObjectId)
| where SubmissionType in ("0")
| summarize count()
);
// baseQuery _FN_ZAP_Successful_Spam
let _FN_ZAP_Successful_Spam = toscalar(
EmailPostDeliveryEvents
| where ActionTrigger == "SpecialAction" and ActionType == "Spam ZAP" and ActionResult == "Success" and Timestamp between (minTime .. maxTime)
| summarize count()
    //Take all our Spam ZAP, and count how many messages we missed and successfully cleaned up.
);
// baseQuery _FN_ZAP_Unsuccessful_Spam
let _FN_ZAP_Unsuccessful_Spam = toscalar(
EmailPostDeliveryEvents
| where ActionTrigger == "SpecialAction" and ActionType == "Spam ZAP" and ActionResult != "Success" and Timestamp between (minTime .. maxTime)
| summarize count()
//Take all our Spam ZAP, and count how many messages we failed to clean up due to error or users/admins/API vendors getting to the message first.
);
// baseQuery _SPAM_ZAP_FP
let _SPAM_ZAP_FP = toscalar(
EmailPostDeliveryEvents
| where ActionTrigger == "SpecialAction" and Action has_any ("Redelivery","Reprocessed") and Timestamp between (minTime .. maxTime)
| join kind=leftsemi (
            EmailEvents
            | where Timestamp between (minTime ..maxTime )
            | where ThreatTypes contains "Spam"
            | project NetworkMessageId, ThreatTypes)
            on NetworkMessageId
| summarize count()
// count all the FPs which were originally Spam, and when we TT'd them were not so we can subtract that from our mailfow catch, and therefore the total true bad.
);
// baseQuery _Spam_Mailflow
let _Spam_Mailflow = toscalar(
EmailEvents
| where EmailDirection == "Inbound" and ThreatTypes == "Spam" and Timestamp between (minTime .. maxTime)
