//Microsoft Defender for Office 365 value for files in SharePoint / OneDrive / Teams: total files processed, how many had a malware detection, and how many were scanned with no detection. A per-period Trend series feeds the tile sparkline.
let gran = {Granularity};
let base = FileMaliciousContentInfo;
let counts = union
(base | summarize Count = count() | extend Cat = "Total Files Processed (SPO/ODB/Teams)", Ord = 1),
(base | where isnotempty(ThreatTypes) | summarize Count = count() | extend Cat = "Files with Malware Detected", Ord = 2),
(base | where isempty(ThreatTypes) | summarize Count = count() | extend Cat = "Files Scanned - No Detection", Ord = 3);
let tagged = union
(base | extend Cat = "Total Files Processed (SPO/ODB/Teams)"),
(base | where isnotempty(ThreatTypes) | extend Cat = "Files with Malware Detected"),
(base | where isempty(ThreatTypes) | extend Cat = "Files Scanned - No Detection");
let trends = tagged | make-series Trend = count() default = 0 on Timestamp step gran by Cat;
counts
| join kind=leftouter (trends) on Cat
| sort by Ord asc
| project Count, Details = Cat, Trend

